const FAV_KEYS = ['en','yo','ig','ha','fr','sw','am'];
let activeLang = 'en';
const downloaded = new Set(['en','yo','sw','ha']);
const choices = { date:'DD/MM/YYYY', currency:'\u20a6 (Nigerian Naira)', number:'1,234.56' };

function t(key,lang){ return (T[key]&&T[key][lang])||(T[key]&&T[key].en)||key; }
function applyI18n(lang){ document.querySelectorAll('[data-i18n]').forEach(el=>{ el.textContent=t(el.dataset.i18n,lang); }); }

function mkFavFlag(flagKey){
    return `<div class="fav-card__flag-wrap"><img src="${FLAG_IMGS[flagKey]}" alt=""></div>`;
}
function mkRowFlag(flagKey){
    return `<div class="lang-row__flag-wrap"><img src="${FLAG_IMGS[flagKey]}" alt=""></div>`;
}

function renderFavs(){
    const c=document.getElementById('favScroll'); c.innerHTML='';
    FAV_KEYS.forEach(code=>{
        const l=LANGS[code],sel=code===activeLang;
        const div=document.createElement('div');
        div.className='fav-card'+(sel?' selected':'');
        div.innerHTML=`${mkFavFlag(l.flagKey)}<span class="fav-card__name">${l.name}</span><span class="fav-card__nat">${l.native}</span><span class="fav-card__tick"><i class="ph-fill ph-check"></i></span>`;
        div.onclick=()=>selectLang(code);
        c.appendChild(div);
    });
}

function renderList(id,region){
    const c=document.getElementById(id); c.innerHTML='';
    Object.entries(LANGS).filter(([,v])=>v.region===region).forEach(([code,l])=>{
        const isActive=code===activeLang,isDl=downloaded.has(code);
        const row=document.createElement('div');
        row.className='lang-row'+(isActive?' active':'');
        row.innerHTML=`${mkRowFlag(l.flagKey)}<div class="lang-row__info"><p class="lang-row__name">${l.name}</p><p class="lang-row__nat">${l.native}</p></div><div class="lang-row__action">${isDl?'<div class="lang-row__check"><i class="ph-fill ph-check"></i></div>':'<div class="lang-row__dl"><i class="ph ph-download-simple"></i></div>'}</div>`;
        row.onclick=()=>selectLang(code);
        c.appendChild(row);
    });
}

function renderAll(){ renderFavs(); renderList('westList','west'); renderList('eastList','east'); renderList('southList','south'); }

function selectLang(code){
    if(code===activeLang) return;
    activeLang=code; downloaded.add(code);
    const l=LANGS[code];
    choices.date=l.date; choices.currency=l.currency; choices.number=l.num;
    document.getElementById('dateVal').textContent=l.date;
    document.getElementById('currencyVal').textContent=l.currency;
    document.getElementById('numberVal').textContent=l.num;
    renderAll();
    if(document.getElementById('autoTog').checked) applyI18n(code);
    showToast('\ud83c\udf0d '+l.name+' selected');
}

const DATE_OPTS=['DD/MM/YYYY','MM/DD/YYYY','YYYY/MM/DD','YYYY-MM-DD'];
const CURR_OPTS=['\u20a6 (Nigerian Naira)','KSh (Kenyan Shilling)','R (South African Rand)','GHS (Ghanaian Cedi)','XOF (CFA Franc)','ETB (Ethiopian Birr)'];
const NUM_OPTS=['1,234.56','1.234,56','1 234,56','1234.56'];
let curModal=null;

function openModal(type){
    curModal=type;
    const titles={date:'Date Format',currency:'Currency Display',number:'Number Format'};
    const opts={date:DATE_OPTS,currency:CURR_OPTS,number:NUM_OPTS};
    const valIds={date:'dateVal',currency:'currencyVal',number:'numberVal'};
    document.getElementById('modalTitle').textContent=titles[type];
    const optsEl=document.getElementById('modalOpts'); optsEl.innerHTML='';
    opts[type].forEach(opt=>{
        const chosen=choices[type]===opt;
        const el=document.createElement('div');
        el.className='modal__opt'+(chosen?' chosen':'');
        el.innerHTML=`<span class="modal__opt-text">${opt}</span><i class="ph-fill ph-check modal__opt-chk"></i>`;
        el.onclick=()=>{ optsEl.querySelectorAll('.modal__opt').forEach(o=>o.classList.remove('chosen')); el.classList.add('chosen'); choices[type]=opt; document.getElementById(valIds[type]).textContent=opt; };
        optsEl.appendChild(el);
    });
    document.getElementById('modalOv').classList.add('open');
}
function closeModal(){ document.getElementById('modalOv').classList.remove('open'); curModal=null; }
function closeModalOutside(e){ if(e.target===document.getElementById('modalOv')) closeModal(); }

let toastTmr;
function showToast(msg){
    const t=document.getElementById('toast');
    document.getElementById('toastMsg').textContent=msg;
    t.classList.add('show'); clearTimeout(toastTmr);
    toastTmr=setTimeout(()=>t.classList.remove('show'),2600);
}

document.addEventListener('DOMContentLoaded',()=>{
    const hb=document.getElementById('hamburgerBtn'),mm=document.getElementById('mobileMenu'),bd=document.getElementById('backdrop');
    let open=false;
    const openMenu=()=>{open=true;hb.classList.add('open');hb.setAttribute('aria-expanded','true');mm.classList.add('open');mm.setAttribute('aria-hidden','false');bd.classList.add('visible');document.body.style.overflow='hidden';};
    const closeMenu=()=>{open=false;hb.classList.remove('open');hb.setAttribute('aria-expanded','false');mm.classList.remove('open');mm.setAttribute('aria-hidden','true');bd.classList.remove('visible');document.body.style.overflow='';};
    hb.addEventListener('click',e=>{e.stopPropagation();open?closeMenu():openMenu();});
    bd.addEventListener('click',closeMenu);
    document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();closeModal();}});
    mm.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setTimeout(closeMenu,120)));
    window.addEventListener('resize',()=>{if(window.innerWidth>=769&&open)closeMenu();});
    document.getElementById('autoTog').addEventListener('change',function(){
        applyI18n(this.checked?activeLang:'en');
        showToast(this.checked?'Auto-translate enabled':'Auto-translate disabled');
    });
    renderAll(); applyI18n('en');

    // ── Drag-to-scroll on fav row (desktop) ──
    const scroller = document.getElementById('favScroll');
    let isDown=false, startX, scrollLeft;
    scroller.addEventListener('mousedown', e=>{
        isDown=true; scroller.classList.add('active');
        startX=e.pageX-scroller.offsetLeft;
        scrollLeft=scroller.scrollLeft;
    });
    scroller.addEventListener('mouseleave',()=>{ isDown=false; scroller.classList.remove('active'); });
    scroller.addEventListener('mouseup',()=>{ isDown=false; scroller.classList.remove('active'); });
    scroller.addEventListener('mousemove', e=>{
        if(!isDown) return;
        e.preventDefault();
        const x=e.pageX-scroller.offsetLeft;
        scroller.scrollLeft=scrollLeft-(x-startX)*1.2;
    });
});